type envSet[E any] struct{ t PpuBenchEnvTests[E] }

func (s envSet[E]) Cases() []run.Case { return EnvCases(s.t) }

func (s envSet[E]) Orphans() []string { return run.Orphans(s.t, append([]string{"Env"}, Methods...)) }

// WithEnv is the form `var Tests = gen.WithEnv[Env](&T{})` of a user's package with an Env.
func WithEnv[E any](t PpuBenchEnvTests[E]) TestSet { return envSet[E]{t} }

// CasesOf are the cases of the user's Tests: a PpuBenchTests (no Env) or a WithEnv.
func CasesOf(t any) []run.Case {
	switch v := t.(type) {
	case TestSet:
		return v.Cases()
	case PpuBenchTests:
		return Cases(v)
	}
	panic(fmt.Sprintf("Tests is a %T: it must be a gen.PpuBenchTests or gen.WithEnv[Env](...)", t))
}

// OrphansOf are the exported methods of the user's Tests that no declared test names (Env is not one).
func OrphansOf(t any) []string {
	if v, ok := t.(TestSet); ok {
		return v.Orphans()
	}
	return run.Orphans(t, Methods)
}
